// Simple Canvas Meteor Dodge game
// Canvas element must have id="game"

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  // Full‑screen canvas
  const resize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  // Player (triangle ship)
  const player = {
    x: canvas.width / 2,
    y: canvas.height - 60,
    size: 20,
    speed: 5,
  };

  // Input handling (arrow keys / mouse)
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));
  canvas.addEventListener('mousemove', e => {
    const rect = canvas.getBoundingClientRect();
    player.x = e.clientX - rect.left;
    player.y = e.clientY - rect.top;
  });

  const meteors = [];
  let spawnTimer = 0;
  let spawnInterval = 1000; // ms
  let lastTime = 0;
  let score = 0;
  let gameOver = false;

  const spawnMeteor = () => {
    const radius = Math.random() * 15 + 10;
    const side = Math.random() < 0.5 ? 'left' : 'right';
    const y = Math.random() * (canvas.height / 2);
    const x = side === 'left' ? -radius : canvas.width + radius;
    const speedX = (side === 'left' ? 1 : -1) * (2 + Math.random() * 2 + score / 1000);
    const speedY = 1 + Math.random() * 2 + score / 2000;
    meteors.push({ x, y, radius, speedX, speedY });
  };

  const update = (delta) => {
    // Player movement (arrow keys)
    if (keys.ArrowLeft) player.x -= player.speed;
    if (keys.ArrowRight) player.x += player.speed;
    if (keys.ArrowUp) player.y -= player.speed;
    if (keys.ArrowDown) player.y += player.speed;
    // Keep within bounds
    player.x = Math.max(0, Math.min(canvas.width, player.x));
    player.y = Math.max(0, Math.min(canvas.height, player.y));

    // Spawn meteors
    spawnTimer += delta;
    if (spawnTimer > spawnInterval) {
      spawnMeteor();
      spawnTimer = 0;
      // Gradually increase difficulty
      if (spawnInterval > 300) spawnInterval -= 10;
    }

    // Update meteors
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.x += m.speedX;
      m.y += m.speedY;
      // Remove off‑screen
      if (m.x < -m.radius || m.x > canvas.width + m.radius || m.y > canvas.height + m.radius) {
        meteors.splice(i, 1);
        score += 1;
        continue;
      }
      // Collision detection (approximate ship as circle)
      const dx = m.x - player.x;
      const dy = m.y - player.y;
      const dist = Math.hypot(dx, dy);
      if (dist < m.radius + player.size / 2) {
        gameOver = true;
      }
    }
  };

  const drawShip = () => {
    ctx.fillStyle = '#0ff';
    ctx.beginPath();
    ctx.moveTo(player.x, player.y - player.size / 2);
    ctx.lineTo(player.x - player.size / 2, player.y + player.size / 2);
    ctx.lineTo(player.x + player.size / 2, player.y + player.size / 2);
    ctx.closePath();
    ctx.fill();
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Meteors
    ctx.fillStyle = '#a52a2a';
    meteors.forEach(m => {
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // Player
    drawShip();
    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 30);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f44';
      ctx.textAlign = 'center';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  };

  const loop = (timestamp) => {
    if (!lastTime) lastTime = timestamp;
    const delta = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(delta);
    draw();
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
